//! Parity proofs for the Rust core. Nothing here is trusted because it
//! was written carefully; it is trusted because it reproduces values
//! generated by the founder's own existing implementations:
//! - the journal must hit the checksums the quarry's Python
//!   state_journal.py produced (scripts/parity-expected.json, generated
//!   by scripts/parity-journal.py running the verbatim source);
//! - the geodesy must reproduce the ENU positions of Twin Earth NYC's
//!   canonical anchor registry (fixtures generated by
//!   scripts/project-anchors.mjs from the verified JS transform).

use serde_json::{json, Value};
use std::fs;
use twin_core::geo::{enu, Origin};
use twin_core::journal::{hash_world_state, StateJournal, ACTION, SNAPSHOT, TICK_BEGIN, TICK_END};

fn read_json(path: &str) -> Value {
    let full = format!("{}/{}", env!("CARGO_MANIFEST_DIR"), path);
    serde_json::from_str(&fs::read_to_string(&full).expect("fixture readable"))
        .expect("fixture parses")
}

fn stats() -> Value {
    json!({
        "buildings": 45172,
        "buildingsWithYear": 44345,
        "buildingsWithNeighborhood": 44929,
        "neighborhoods": 38,
        "origin": {"lat": 40.758, "lon": -73.9855, "name": "Times Square"}
    })
}

fn build_journal() -> (StateJournal, String) {
    let world_hash = hash_world_state(&stats());
    let mut j = StateJournal::new();
    j.append(SNAPSHOT, 0, stats());
    j.append(TICK_BEGIN, 1, json!({"action": "ask"}));
    j.append(ACTION, 1, json!({
        "kind": "ask",
        "via": "model",
        "question": "pre-war buildings under 50 feet in the East Village",
        "query": {"nb": "East Village", "yrMax": 1944, "hMax": 15.24},
        "matches": 589,
        "sampleBins": [1004983]
    }));
    j.append(TICK_END, 1, json!({"world_hash": world_hash}));
    (j, world_hash)
}

#[test]
fn journal_matches_the_quarrys_python_checksums() {
    let expected = read_json("../scripts/parity-expected.json");
    let (j, world_hash) = build_journal();
    assert_eq!(world_hash, expected["worldHash"].as_str().unwrap(), "world hash");
    let checksums: Vec<&str> = j.entries().iter().map(|e| e.checksum.as_str()).collect();
    let expected_checksums: Vec<&str> = expected["checksums"]
        .as_array()
        .unwrap()
        .iter()
        .map(|c| c.as_str().unwrap())
        .collect();
    assert_eq!(checksums, expected_checksums, "entry checksums");
    assert!(j.verify_chain(), "chain verifies");
    assert_eq!(
        j.checksum_until_tick(1),
        expected["checksumUntilTick1"].as_str().unwrap(),
        "checksum until tick 1"
    );
}

#[test]
fn journal_replay_is_deterministic() {
    let (a, _) = build_journal();
    let (b, _) = build_journal();
    assert_eq!(a.last_checksum(), b.last_checksum(), "same inputs, same head");
}

#[test]
fn geodesy_reproduces_the_anchor_registry() {
    let registry = read_json("tests/fixtures/anchors.json");
    let golden = read_json("tests/fixtures/anchors-enu.json");
    let o = &registry["metadata"]["origin"];
    let origin = Origin {
        lat: o["lat"].as_f64().unwrap(),
        lon: o["lon"].as_f64().unwrap(),
        elev: o["elev"].as_f64().unwrap(),
    };
    let golden_by_id = |id: &str| {
        golden
            .as_array()
            .unwrap()
            .iter()
            .find(|g| g["id"].as_str().unwrap() == id)
            .cloned()
            .unwrap()
    };
    let mut checked = 0;
    for anchor in registry["anchors"].as_array().unwrap() {
        let p = enu(
            &origin,
            anchor["lat"].as_f64().unwrap(),
            anchor["lon"].as_f64().unwrap(),
            anchor["elev"].as_f64().unwrap(),
        );
        let g = golden_by_id(anchor["id"].as_str().unwrap());
        for (got, want, axis) in [
            (p.east, g["east"].as_f64().unwrap(), "east"),
            (p.north, g["north"].as_f64().unwrap(), "north"),
            (p.up, g["up"].as_f64().unwrap(), "up"),
        ] {
            assert!(
                (got - want).abs() < 1e-6,
                "anchor {} {}: rust {} vs golden {}",
                anchor["id"].as_str().unwrap(),
                axis,
                got,
                want
            );
        }
        checked += 1;
    }
    assert_eq!(checked, 25, "all geo anchors checked");
}
